<?php
declare(strict_types=1);
require_once __DIR__.'/MailSettings.php';
require_once __DIR__.'/SmtpTransport.php';
final class OrderMail
{
    public function __construct(private PDO $db,private string $directory,private array $config=[],private ?SmtpTransport $transport=null){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    public static function directory():string{$c=function_exists('jingoConfig')?jingoConfig():[];return $c['MEDIA_DIR']??(getenv('MEDIA_DIR')?:dirname(__DIR__).'/storage/media');}
    public static function register(PDO $db,string $id,string $key):void{if(!$db->inTransaction())throw new LogicException('Mail registration requires transaction.');$q=$db->prepare('INSERT INTO jingo_order_mail_keys(order_id,secret) VALUES (?,?)');$q->execute([$id,(new SecretCipher(self::directory()))->encrypt($key)]);}
    public static function enqueue(PDO $db,string $id,string $event,int $version):void
    {
        if(!$db->inTransaction())throw new LogicException('Mail enqueue requires transaction.');$c=$db->query("SELECT data FROM jingo_settings WHERE id='smtp'")->fetchColumn();if($c===false||!(json_decode($c,true,512,JSON_THROW_ON_ERROR)['enabled']??false))return;$q=$db->prepare('SELECT order_id FROM jingo_partner_orders WHERE order_id=?');$q->execute([$id]);if($q->fetchColumn())return;$q=$db->prepare('SELECT order_id FROM jingo_order_mail_keys WHERE order_id=?');$q->execute([$id]);if(!$q->fetchColumn())return;$q=$db->prepare("INSERT INTO jingo_mail_outbox(id,order_id,event,last_error) VALUES (?,?,?,'') ON DUPLICATE KEY UPDATE id=id");$q->execute([$id.':'.$version.':'.$event,$id,$event]);
    }
    private static function uuid(mixed $v):string{if(!is_string($v)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$v))throw new HttpError(400,'Mã yêu cầu không hợp lệ.');return strtolower($v);}
    private function tx(callable $fn,bool $snapshot=false):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL '.($snapshot?'REPEATABLE READ':'READ COMMITTED'));$this->db->beginTransaction();try{$r=$fn();$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    public function status(string $id):array
    {
        $id=self::uuid($id);if(!$this->query('SELECT id FROM jingo_orders WHERE id=?',[$id])->fetchColumn())throw new HttpError(404,'Không tìm thấy đơn.');$partner=$this->query('SELECT order_id FROM jingo_partner_orders WHERE order_id=?',[$id])->fetchColumn();$key=$this->query('SELECT order_id FROM jingo_order_mail_keys WHERE order_id=?',[$id])->fetchColumn();$rows=$this->query('SELECT id,event,status,attempts,last_error,created_at,sent_at,next_at FROM jingo_mail_outbox WHERE order_id=? ORDER BY created_at DESC,id DESC LIMIT 100',[$id])->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['attempts']=(int)$r['attempts'];if($r['last_error']!=='')$r['last_error']='SMTP gửi thất bại; kiểm tra cấu hình, khóa và URL website.';}unset($r);return ['enabled'=>(new MailSettings($this->db,$this->directory))->read()['enabled'],'eligible'=>!$partner&&!!$key,'reason'=>$partner?'PARTNER':(!$key?'NO_ACCESS_KEY':null),'data'=>$rows];
    }
    private function eligible(string $id):void{$s=$this->status($id);if(!$s['eligible'])throw new HttpError(409,$s['reason']==='PARTNER'?'Đơn CTV nhận vé trong tài khoản CTV.':'Đơn cũ chưa lưu khóa email. Không tự tạo khóa mới.');if(!$s['enabled'])throw new HttpError(409,'Bật và kiểm tra SMTP trước khi xếp email vé.');}
    public function resend(string $id,array $in,string $actor):array
    {
        $id=self::uuid($id);if(count($in)!==1)throw new HttpError(400,'Yêu cầu không hợp lệ.');$request=self::uuid($in['requestId']??null);return $this->tx(function()use($id,$request,$actor){if(!$this->query('SELECT id FROM jingo_orders WHERE id=? FOR UPDATE',[$id])->fetchColumn())throw new HttpError(404,'Không tìm thấy đơn.');$key='RESEND:'.$request;$old=$this->query('SELECT order_id FROM jingo_mail_outbox WHERE id=?',[$key])->fetchColumn();if($old!==false){if($old!==$id)throw new HttpError(409,'Mã yêu cầu đã dùng cho đơn khác.');return ['ok'=>true];}$this->eligible($id);$this->query("INSERT INTO jingo_mail_outbox(id,order_id,event,last_error) VALUES (?,?,'STATUS','')",[$key,$id]);$this->audit($actor,'order.mail.resend',$id);return ['ok'=>true];});
    }
    private function audit(string $actor,string $event,string $id):void{$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,$event,$id]);}
    public function retry(string $order,string $job,string $actor):array
    {
        $order=self::uuid($order);if(strlen($job)>190)throw new HttpError(400,'Email không hợp lệ.');return $this->tx(function()use($order,$job,$actor){$this->query('SELECT id FROM jingo_orders WHERE id=? FOR UPDATE',[$order]);$state=$this->query('SELECT status FROM jingo_mail_outbox WHERE id=? AND order_id=? FOR UPDATE',[$job,$order])->fetchColumn();if($state===false)throw new HttpError(404,'Không tìm thấy email trong đơn.');if($state!=='FAILED')throw new HttpError(409,'Chỉ thử lại email FAILED.');$this->eligible($order);$this->query("UPDATE jingo_mail_outbox SET status='PENDING',attempts=0,next_at=UTC_TIMESTAMP(6),last_error='' WHERE id=?",[$job]);$this->audit($actor,'order.mail.retry',$order);return ['ok'=>true];});
    }
    public function journal(array $in):array
    {
        if(array_diff(array_keys($in),['q','status','page'])||array_key_exists('q',$in)&&!is_string($in['q'])||array_key_exists('status',$in)&&!in_array($in['status'],['PENDING','SENDING','SENT','FAILED'],true)||array_key_exists('page',$in)&&(!is_int($in['page'])&&!is_string($in['page'])||!preg_match('/^[1-9][0-9]{0,5}$/D',(string)$in['page'])))throw new HttpError(400,'Bộ lọc email không hợp lệ.');$q=trim($in['q']??'');if(mb_strlen($q,'UTF-8')>120)throw new HttpError(400,'Từ khóa quá dài.');
        return $this->tx(function()use($in,$q){$where=[];$args=[];if(isset($in['status'])){$where[]='m.status=?';$args[]=$in['status'];}if($q!==''){$where[]='LOCATE(LOWER(?),LOWER(o.code))>0';$args[]=$q;}$sql=' FROM jingo_mail_outbox m JOIN jingo_orders o ON o.id=m.order_id'.($where?' WHERE '.implode(' AND ',$where):'');$total=(int)$this->query('SELECT COUNT(*)'.$sql,$args)->fetchColumn();$page=min((int)($in['page']??1),max(1,(int)ceil($total/25)));$rows=$this->query('SELECT m.id,m.order_id,o.code,m.event,m.status,m.attempts,m.next_at,m.created_at,m.sent_at,m.last_error'.$sql.' ORDER BY m.created_at DESC,m.id DESC LIMIT 25 OFFSET '.(($page-1)*25),$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['attempts']=(int)$r['attempts'];if($r['last_error']!=='')$r['last_error']='SMTP gửi thất bại; kiểm tra cấu hình, khóa và URL website.';}unset($r);return ['data'=>$rows,'total'=>$total,'page'=>$page,'pageSize'=>25];},true);
    }
    private function cartMessage(array $job,string $key,string $origin,bool $en):array
    {
        $cart=$this->query('SELECT c.* FROM jingo_cart_orders m JOIN jingo_carts c ON c.id=m.cart_id WHERE m.order_id=?',[$job['order_id']])->fetch(PDO::FETCH_ASSOC);if(!$cart||!hash_equals($cart['access_hash'],hash('sha256',$key)))throw new RuntimeException('Cart mail access mismatch.');$rows=$this->query('SELECT o.* FROM jingo_cart_orders m JOIN jingo_orders o ON o.id=m.order_id WHERE m.cart_id=? ORDER BY m.position',[$cart['id']])->fetchAll(PDO::FETCH_ASSOC);if(!$rows)throw new RuntimeException('Empty cart.');$contact=json_decode($rows[0]['contact'],true,512,JSON_THROW_ON_ERROR);$title=$job['event']==='CART_PAY'?($en?'Cart payment recorded':'Đã ghi nhận thu giỏ vé'):($en?'Ticket cart received':'Đã nhận giỏ vé');$text=[$title,$cart['code']];foreach($rows as $r){$s=json_decode($r['snapshot'],true,512,JSON_THROW_ON_ERROR);$text[]=$r['code'].' · '.$s['productName'].' · '.$s['variantName'].' · '.$s['date'].' · '.number_format($s['total'],0,',','.').' VND · '.$r['booking_status'].' / '.$r['payment_status'];}$text[]=$en?'Open your private link for current status and original ticket files. Booking, payment and delivery are separate.':'Mở liên kết riêng để xem trạng thái mới nhất và nhận file vé gốc. Đặt vé, thu tiền và giao vé là các bước riêng.';$text[]=$origin.($en?'/en/carts':'/gio-ve').'#'.$cart['code'].':'.$key;$text[]=$en?'Keep this link private.':'Giữ kín liên kết này.';return [$contact['email'],$title.' · '.$cart['code'],implode("\n\n",$text)];
    }
    private function message(array $job,array $row):array
    {
        $s=json_decode($row['snapshot'],true,512,JSON_THROW_ON_ERROR);$c=json_decode($row['contact'],true,512,JSON_THROW_ON_ERROR);$en=($s['locale']??'vi')==='en';$titles=$en?['CREATED'=>'Booking received','PAY'=>'Payment recorded','CONFIRM'=>'Booking confirmed','CANCEL'=>'Booking cancelled','DELIVER'=>'Your tickets are available','INSTRUCTIONS'=>'Booking instructions']:['CREATED'=>'Đã nhận đơn đặt vé','PAY'=>'Đã ghi nhận thu tiền','CONFIRM'=>'Đã xác nhận đặt vé','CANCEL'=>'Đơn đặt vé đã hủy','DELIVER'=>'Vé của bạn đã được cập nhật','INSTRUCTIONS'=>'Hướng dẫn đơn đặt vé'];$event=$job['event'];if($row['booking_status']==='CANCELLED')$event='CANCEL';elseif($event==='CANCEL'||$event==='CONFIRM'&&$row['booking_status']!=='CONFIRMED')$event='STATUS';$title=$titles[$event]??($en?'Booking update':'Cập nhật đơn đặt vé');$base=$this->config['PUBLIC_BASE_URL']??'';$u=parse_url($base);if(!$u||!isset($u['scheme'],$u['host'])||isset($u['user'])||isset($u['pass'])||isset($u['query'])||isset($u['fragment'])||!in_array($u['scheme'],['http','https'],true)||($this->config['APP_ENV']??'production')!=='development'&&$u['scheme']!=='https')throw new RuntimeException('Invalid public URL.');$key=(new SecretCipher($this->directory))->decrypt($row['secret']);if(!preg_match('/^[a-f0-9]{64}$/iD',$key)||!hash_equals($row['access_hash'],hash('sha256',$key)))throw new RuntimeException('Mail key does not match order.');
        $origin=$u['scheme'].'://'.$u['host'].(isset($u['port'])?':'.$u['port']:'');if(str_starts_with($job['event'],'CART_'))return $this->cartMessage($job,$key,$origin,$en);$link=$origin.($en?'/en/orders':'/tra-cuu').'#'.$row['code'].':'.$key;$booking=$en?['REQUESTED'=>'Pending confirmation','CONFIRMED'=>'Confirmed','CANCELLED'=>'Cancelled']:['REQUESTED'=>'Chờ xác nhận','CONFIRMED'=>'Đã đặt vé','CANCELLED'=>'Đã hủy'];$payment=$en?['UNPAID'=>'Unpaid','PAID'=>'Paid','CREDIT'=>'Partner credit']:['UNPAID'=>'Chưa thu tiền','PAID'=>'Đã thu tiền','CREDIT'=>'Công nợ CTV'];$text=[$title,$row['code'],$s['productName'],$s['variantName'],($en?'Visit date: ':'Ngày sử dụng: ').$s['date'],($en?'Total: ':'Tổng tiền: ').number_format($s['total'],0,',','.').' VND',($en?'Booking: ':'Đơn: ').($booking[$row['booking_status']]??$row['booking_status']),($en?'Payment: ':'Thanh toán: ').($payment[$row['payment_status']]??$row['payment_status']),$row['instructions'],$en?'Booking, payment and ticket delivery are separate. Use your private link for the latest status and original ticket files.':'Đặt vé, thu tiền và giao vé là các trạng thái riêng. Xem trạng thái mới nhất và nhận file vé gốc tại liên kết riêng.',$link,$en?'Keep this link private.':'Giữ kín liên kết này.'];return [$c['email'],$title.' · '.$row['code'],implode("\n\n",array_filter($text,fn($v)=>$v!==''))];
    }
    public function processOne():string
    {
        $c=(new MailSettings($this->db,$this->directory))->credentials();if(!$c)return 'disabled';$lock='jm-mail-'.substr(hash('sha256',(string)$this->query('SELECT DATABASE()')->fetchColumn()),0,40);if((int)$this->query('SELECT GET_LOCK(?,0)',[$lock])->fetchColumn()!==1)return 'busy';
        try{
            $this->db->beginTransaction();try{$job=$this->query("SELECT * FROM jingo_mail_outbox WHERE status IN ('PENDING','SENDING') AND next_at<=UTC_TIMESTAMP(6) ORDER BY created_at,id LIMIT 1 FOR UPDATE")->fetch(PDO::FETCH_ASSOC);if(!$job){$this->db->commit();return 'empty';}if((int)$job['attempts']>=5){$this->query("UPDATE jingo_mail_outbox SET status='FAILED',last_error=? WHERE id=?",['Đã hết số lần thử; kiểm tra hộp thư trước khi gửi lại.',$job['id']]);$this->db->commit();return 'failed';}$attempt=(int)$job['attempts']+1;$this->query("UPDATE jingo_mail_outbox SET status='SENDING',attempts=?,next_at=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 120 SECOND) WHERE id=?",[$attempt,$job['id']]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
            try{
                $row=$this->query('SELECT o.code,o.snapshot,o.contact,o.instructions,o.booking_status,o.payment_status,o.access_hash,k.secret FROM jingo_orders o JOIN jingo_order_mail_keys k ON k.order_id=o.id WHERE o.id=?',[$job['order_id']])->fetch(PDO::FETCH_ASSOC);if(!$row||$this->query('SELECT order_id FROM jingo_partner_orders WHERE order_id=?',[$job['order_id']])->fetchColumn())throw new RuntimeException('Order is no longer eligible.');[$to,$subject,$text]=$this->message($job,$row);($this->transport??new SmtpTransport())->send($c,$to,$subject,$text,$job['id']);$this->query("UPDATE jingo_mail_outbox SET status='SENT',sent_at=UTC_TIMESTAMP(6),last_error='' WHERE id=? AND status='SENDING' AND attempts=?",[$job['id'],$attempt]);return 'sent';
            }catch(Throwable){$state=$attempt>=5?'FAILED':'PENDING';$delay=60*(2**min($attempt-1,6));$this->query("UPDATE jingo_mail_outbox SET status=?,last_error=?,next_at=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL ".$delay." SECOND) WHERE id=? AND status='SENDING' AND attempts=?",[$state,'SMTP gửi thất bại; kiểm tra cấu hình và gửi lại từ đơn.',$job['id'],$attempt]);return strtolower($state);}
        }finally{$this->query('SELECT RELEASE_LOCK(?)',[$lock]);}
    }
}
